// Ce site n'a pas de service worker. Ce fichier existe pour nettoyer celui de
// l'ancien site : quand le cours « Du noyau au réacteur » était à la racine du
// domaine, il y enregistrait /sw.min.js (cache hors ligne du thème Chirpy), qui
// pouvait ensuite resservir de vieilles pages, y compris pour /recettes/.
//
// Les navigateurs qui l'avaient installé vérifient ce fichier à chaque visite :
// ils reçoivent cette version, qui vide les caches et se désinscrit. Les autres
// ne le chargent jamais. Les deux sous-sites ont leur propre service worker,
// limité à leur dossier, et le recréent au besoin.

self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const nom of await caches.keys()) await caches.delete(nom);
      await self.registration.unregister();
    })()
  );
});
